using System.Globalization;
using FatturaFacile.Domain.Entities;

namespace FatturaFacile.Application.Features.Reports.Builders;

/// <summary>
/// Texts generated by the invoice builder in the language of the template (IT, DE, FR, EN).
/// </summary>
public static class InvoiceLabels
{
    private static readonly Dictionary<string, string[]> _totalLabels = new(StringComparer.Ordinal)
    {
        ["IT"] = ["Totale imponibile", "Sconto", "Totale IVA", "Arrotondamento", "Totale documento", "Ritenuta d'acconto", "IVA in scissione dei pagamenti", "Imposta di bollo", "Netto a pagare"],
        ["DE"] = ["Total netto", "Rabatt", "Total MWST", "Rundung", "Total brutto", "Quellensteuer", "MWST Split Payment", "Stempelsteuer", "Zu bezahlen"],
        ["FR"] = ["Total net", "Rabais", "Total TVA", "Arrondi", "Total brut", "Retenue à la source", "TVA split payment", "Droit de timbre", "Montant à payer"],
        ["EN"] = ["Net total", "Discount", "VAT total", "Rounding", "Gross total", "Withholding tax", "Split payment VAT", "Stamp duty", "Amount payable"],
    };

    /// <summary>
    /// Returns the label of a total row.
    /// </summary>
    /// <param name="language">The two-letter language code in upper case.</param>
    /// <param name="row">The row.</param>
    /// <returns>The label.</returns>
    public static string Total(string language, InvoiceTotalRow row) =>
        (_totalLabels.TryGetValue(language, out var labels) ? labels : _totalLabels["IT"])[(int)row];

    /// <summary>
    /// Returns the document title.
    /// </summary>
    /// <param name="language">The two-letter language code in upper case.</param>
    /// <param name="creditNote">Whether the document is a credit note.</param>
    /// <returns>The title.</returns>
    public static string Title(string language, bool creditNote) => (language, creditNote) switch
    {
        ("DE", false) => "Rechnung",
        ("DE", true) => "Gutschrift",
        ("FR", false) => "Facture",
        ("FR", true) => "Note de crédit",
        ("EN", false) => "Invoice",
        ("EN", true) => "Credit note",
        (_, true) => "Nota di credito",
        _ => "Fattura",
    };

    /// <summary>
    /// Returns the mandatory notes for split payment, reverse charge, withholding tax and stamp duty.
    /// </summary>
    /// <param name="language">The two-letter language code in upper case.</param>
    /// <param name="invoice">The invoice.</param>
    /// <returns>The notes, one per line.</returns>
    public static string LegalNotes(string language, Invoice invoice)
    {
        ArgumentNullException.ThrowIfNull(invoice);
        List<string> notes = [];
        var english = string.Equals(language, "EN", StringComparison.Ordinal);

        if (invoice.SplitPayment)
        {
            notes.Add(english
                ? "Split payment - art. 17-ter Italian Presidential Decree 633/1972: VAT paid by the public administration."
                : "Scissione dei pagamenti - art. 17-ter DPR 633/1972: IVA versata dall'ente pubblico.");
        }

        if (invoice.ReverseCharge)
        {
            notes.Add(english
                ? "Reverse charge: VAT due by the customer."
                : "Inversione contabile (reverse charge): IVA a carico del committente.");
        }

        if (invoice.WithholdingTaxEnabled && invoice.WithholdingTaxPercent is { } rate)
        {
            notes.Add(english
                ? string.Create(CultureInfo.InvariantCulture, $"Withholding tax {rate:0.##}% deducted from the amount payable.")
                : string.Create(CultureInfo.InvariantCulture, $"Ritenuta d'acconto {rate:0.##}% trattenuta dall'importo da pagare."));
        }

        if (invoice.StampDutyApplied)
        {
            notes.Add(english
                ? "Stamp duty paid virtually (Italian Ministerial Decree 17/06/2014)."
                : "Imposta di bollo assolta in modo virtuale ai sensi del D.M. 17/06/2014.");
        }

        return string.Join(Environment.NewLine, notes);
    }
}
